import { expect, test } from "@playwright/test";

import { getEncounterNotesUrl, saveRecording } from "../../support/care";
import { installCursor, Pointer } from "../../support/pointer";

// Records "How to Start a Discussion" in the encounter Notes tab.
// Step titles match the flow doc headings so the recording and the doc stay aligned.
const PAUSE = 900;

// Suggested titles from NoteManager.tsx, in the order the flow doc lists them.
// Care drops a title from the list once a discussion in this context already uses it.
const SUGGESTED_TITLES = [
  "Treatment Plan",
  "Medication Notes",
  "Care Coordination",
  "General Notes",
  "Patient History",
  "Referral Notes",
  "Lab Results Discussion",
];

test("How to Start a Discussion", async ({ page }) => {
  const notesUrl = await getEncounterNotesUrl();
  await installCursor(page);
  const pointer = new Pointer(page);

  await test.step("1. Go to the Notes tab", async () => {
    await page.goto(notesUrl);
    await expect(
      page.getByRole("button", { name: "New", exact: true }),
    ).toBeVisible();
    await pointer.reset();
    await page.waitForTimeout(PAUSE);
  });

  let usedTitle = "";

  await test.step("2. Open the Start New Discussion dialog", async () => {
    await pointer.click(
      page.getByRole("button", { name: "New", exact: true }),
    );
    await expect(page.getByRole("dialog")).toBeVisible();
    await page.waitForTimeout(PAUSE);
  });

  await test.step("3. Enter the discussion title", async () => {
    const dialog = page.getByRole("dialog");

    for (const title of SUGGESTED_TITLES) {
      const chip = dialog.getByText(title, { exact: true });
      if (await chip.isVisible().catch(() => false)) {
        usedTitle = title;
        await pointer.click(chip);
        break;
      }
    }

    if (!usedTitle) {
      // No suggestion left unused — type a title that cannot collide with fixture data.
      usedTitle = `${faker.word.words(2)} ${faker.string.alphanumeric(6)}`;
      const titleInput = dialog.getByPlaceholder("Enter discussion title...");
      await pointer.click(titleInput);
      await titleInput.fill(usedTitle);
    }

    await page.waitForTimeout(PAUSE);
  });

  await test.step("4. Create the discussion", async () => {
    await pointer.click(
      page.getByRole("dialog").getByRole("button", { name: "Create" }),
    );
    await expect(page.getByText("Thread created successfully")).toBeVisible();
    await expect(
      page.getByPlaceholder("Type your message..."),
    ).toBeVisible();
  });

  // Hold on the final screen so the outcome is visible in the video.
  await page.waitForTimeout(2500);

  await saveRecording(
    page,
    "Clinical/Clinical Notes/media/1. Start a discussion.mp4",
  );
});
"}

